", "path": "app/phone.py"}, {"content": """"ASGI security layer: host, origin, token, rate limit, headers, body size."""
import hmac
import json
import os
import time
from collections import defaultdict, deque
from typing import Any, Deque, Dict, Optional, Tuple
from urllib.parse import parse_qsl, urlencode, urlparse

ALLOWED_DEFAULT_HOSTS: frozenset = frozenset({"127.0.0.1", "localhost"})
RATE_LIMIT_ENV: Tuple[str, ...] = ("BLACKOUT_RATE_LIMIT", "BLACKOUT_RATE_LIMIT_PER_MINUTE")
_window_state: Dict[str, Deque[float]] = defaultdict(deque)
_window_config: Dict[str, Tuple[int, float]] = {}
COOKIE_NAME: str = "blackout_access_token"
CSP: str = "default-src 'self'; script-src 'self' blob:; worker-src 'self' blob:; connect-src 'self' ws: wss:; img-src 'self' blob: data:; style-src 'self'; media-src 'self' blob:; frame-ancestors 'none'; base-uri 'none'; form-action 'self'"
SECURITY_HEADERS: Tuple[Tuple[str, str], ...] = (("x-content-type-options", "nosniff"), ("referrer-policy", "no-referrer"), ("content-security-policy", CSP), ("x-frame-options", "DENY"))


def _host_name(host: str) -> str:
    value: str = host.strip().lower()
    if value.startswith("["):
        end: int = value.find("]")
        return value[1:end] if end > 0 else value
    if value.count(":") == 1:
        return value.split(":", 1)[0]
    return value


def allowed_hosts() -> set:
    hosts: set = set(ALLOWED_DEFAULT_HOSTS)
    raw: str = os.environ.get("BLACKOUT_ALLOWED_HOSTS", "")
    for item in raw.replace(";", ",").split(","):
        if item.strip():
            hosts.add(_host_name(item.strip()))
    return hosts


def is_allowed_host(host: Optional[str]) -> bool:
    return bool(host) and _host_name(host or "") in allowed_hosts()


def origin_allowed(origin: Optional[str], host: Optional[str]) -> bool:
    if not origin:
        return True
    parsed: Any = urlparse(origin)
    return bool(parsed.netloc) and parsed.netloc.lower() == (host or "").lower()


def _rate_settings() -> Tuple[int, float]:
    limit_raw: str = ""
    for name in RATE_LIMIT_ENV:
        if os.environ.get(name):
            limit_raw = os.environ[name]
            break
    try:
        limit: int = int(limit_raw) if limit_raw else 300
    except ValueError:
        limit = 300
    try:
        window: float = float(os.environ.get("BLACKOUT_RATE_WINDOW", os.environ.get("BLACKOUT_RATE_WINDOW_SECONDS", "60")))
    except ValueError:
        window = 60.0
    return max(0, limit), max(0.001, window)


def reset_rate_limit() -> None:
    _window_state.clear()
    _window_config.clear()


clear_rate_limits = reset_rate_limit
clear_rate_limit = reset_rate_limit


def check_rate_limit(client_ip: str, now: Optional[float] = None) -> bool:
    limit, window = _rate_settings()
    if limit <= 0:
        return False
    stamp: float = time.monotonic() if now is None else now
    config: Tuple[int, float] = (limit, window)
    if _window_config.get(client_ip) != config:
        _window_state[client_ip].clear()
        _window_config[client_ip] = config
    bucket: Deque[float] = _window_state[client_ip]
    while bucket and stamp - bucket[0] >= window:
        bucket.popleft()
    if len(bucket) >= limit:
        return False
    bucket.append(stamp)
    return True


def configured_token() -> str:
    return os.environ.get("BLACKOUT_ACCESS_TOKEN", "")


def _headers(scope: Dict[str, Any]) -> Dict[str, str]:
    out: Dict[str, str] = {}
    for key, value in scope.get("headers", []):
        out[key.decode("latin-1").lower()] = value.decode("latin-1")
    return out


def _provided_token(scope: Dict[str, Any], headers: Dict[str, str]) -> Tuple[Optional[str], bool]:
    pairs: list = parse_qsl(scope.get("query_string", b"").decode("latin-1"), keep_blank_values=True)
    in_query: bool = any(k == "token" for k, _ in pairs)
    for key, value in pairs:
        if key == "token":
            return value, True
    cookie: str = headers.get("cookie", "")
    for part in cookie.split(";"):
        if "=" in part:
            key, value = part.strip().split("=", 1)
            if key == COOKIE_NAME:
                return value, in_query
    return None, in_query


def _tokens_match(provided: Optional[str], expected: str) -> bool:
    if provided is None:
        return False
    return hmac.compare_digest(provided.encode("utf-8"), expected.encode("utf-8"))


def _token_ok(scope: Dict[str, Any], headers: Dict[str, str]) -> bool:
    expected: str = configured_token()
    if not expected:
        return True
    provided, _ = _provided_token(scope, headers)
    return _tokens_match(provided, expected)


def _body_limit(scope: Dict[str, Any]) -> int:
    path: str = str(scope.get("path", ""))
    if path in ("/api/transcribe",) or path.endswith("/turns"):
        return 32 * 1024 * 1024 + 1024 * 1024
    if path.endswith("/sketches"):
        return 8 * 1024 * 1024 + 1024 * 1024
    if path.startswith("/api/"):
        return 65536
    return 32 * 1024 * 1024 + 1024 * 1024


def _error(status: int, code: str, message: str) -> Tuple[int, bytes]:
    body: bytes = json.dumps({"error": {"code": code, "message": message}}, ensure_ascii=False).encode("utf-8")
    return status, body


def _security_headers_bytes() -> list:
    return [(key.encode("latin-1"), value.encode("latin-1")) for key, value in SECURITY_HEADERS]


class SecurityMiddleware:
    """Pure ASGI middleware, so WebSockets and body limits are covered pre-read."""
    def __init__(self, app: Any) -> None:
        self.app: Any = app

    async def __call__(self, scope: Dict[str, Any], receive: Any, send: Any) -> None:
        if scope.get("type") not in ("http", "websocket"):
            await self.app(scope, receive, send)
            return
        headers: Dict[str, str] = _headers(scope)
        host: Optional[str] = headers.get("host")
        if not is_allowed_host(host):
            await self._reject(scope, send, 400, "invalid_host", "请求地址不正确。", 1008)
            return
        method: str = str(scope.get("method", "GET")).upper()
        path: str = str(scope.get("path", ""))
        if scope.get("type") == "http" and method in ("POST", "PUT", "PATCH") and path.startswith("/api/"):
            if "transfer-encoding" in headers and "content-length" not in headers:
                await self._reject(scope, send, 411, "length_required", "请求缺少长度信息，请重试。", 1008)
                return
        if scope.get("type") == "websocket" or method != "GET":
            if not origin_allowed(headers.get("origin"), host):
                await self._reject(scope, send, 403, "forbidden_origin", "来源不正确。", 1008)
                return
        expected: str = configured_token()
        if expected:
            provided, in_query = _provided_token(scope, headers)
            valid: bool = _tokens_match(provided, expected)
            if in_query and valid and scope.get("type") == "http":
                await self._redirect_without_token(scope, send)
                return
            if not valid:
                await self._reject(scope, send, 401, "unauthorized", "访问令牌不正确。", 1008)
                return
        if scope.get("type") == "http":
            if path.startswith("/api/"):
                client: Any = scope.get("client") or ("unknown", 0)
                if not check_rate_limit(str(client[0])):
                    await self._reject(scope, send, 429, "rate_limited", "请求太频繁，请稍后再试。", 1008)
                    return
            length: Optional[str] = headers.get("content-length")
            if length is not None:
                try:
                    too_big: bool = int(length) > _body_limit(scope)
                except ValueError:
                    too_big = True
                if too_big:
                    await self._reject(scope, send, 400, "invalid_input", "内容太大，请缩小后再试。", 1008)
                    return
            await self.app(scope, receive, self._send_with_headers(send))
            return
        await self.app(scope, receive, send)

    def _send_with_headers(self, send: Any) -> Any:
        async def wrapped(message: Dict[str, Any]) -> None:
            if message.get("type") == "http.response.start":
                headers: list = list(message.get("headers", []))
                present: set = {k.decode("latin-1").lower() for k, _ in headers}
                for key, value in SECURITY_HEADERS:
                    if key not in present:
                        headers.append((key.encode("latin-1"), value.encode("latin-1")))
                message = dict(message)
                message["headers"] = headers
            await send(message)
        return wrapped

    async def _reject(self, scope: Dict[str, Any], send: Any, status: int, code: str, message: str, ws_code: int) -> None:
        if scope.get("type") == "websocket":
            await send({"type": "websocket.close", "code": ws_code})
            return
        status_out, body = _error(status, code, message)
        headers: list = [(b"content-type", b"application/json"), (b"content-length", str(len(body)).encode())] + _security_headers_bytes()
        await send({"type": "http.response.start", "status": status_out, "headers": headers})
        await send({"type": "http.response.body", "body": body})

    async def _redirect_without_token(self, scope: Dict[str, Any], send: Any) -> None:
        pairs: list = [(k, v) for k, v in parse_qsl(scope.get("query_string", b"").decode("latin-1"), keep_blank_values=True) if k != "token"]
        path: str = str(scope.get("path", "/"))
        location: str = path + (("?" + urlencode(pairs)) if pairs else "")
        cookie: str = f"{COOKIE_NAME}={configured_token()}; Path=/; HttpOnly; Secure; SameSite=Strict"
        headers: list = [(b"location", location.encode("latin-1")), (b"set-cookie", cookie.encode("latin-1")), (b"content-length", b"0")] + _security_headers_bytes()
        await send({"type": "http.response.start", "status": 303, "headers": headers})
        await send({"type": "http.response.body", "body": b""})
", "path": "app/security.py"}, {"content": """"Persistent session storage and per-session locks."""
import copy
import json
import logging
import os
import re
import threading
import time
import uuid
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Dict, List, Optional

from app.state import new_state

logger: logging.Logger = logging.getLogger(__name__)
_ID_RE: re.Pattern = re.compile(r"[0-9a-f]{32}")
_locks: Dict[str, threading.RLock] = {}
_locks_guard: threading.Lock = threading.Lock()
_cache: Dict[str, Dict[str, Any]] = {}
_outbox: Dict[str, List[Dict[str, str]]] = {}
_live: Dict[str, Dict[str, str]] = {}
# Live microphone states: the user and the AI are never both "speaking".
LIVE_MIC_VALUES: frozenset = frozenset({"listening", "paused", "user_speaking", "ai_speaking", "offline"})
DEFAULT_LIVE: Dict[str, str] = {"mic": "offline", "partial": "", "last_user": "", "last_reply": "", "last_action": "", "last_reason": ""}
_REPLACE_DELAYS: List[float] = [0.05, 0.1, 0.15, 0.2, 0.25, 0.25]


def now_iso() -> str:
    """Current UTC timestamp."""
    return datetime.now(timezone.utc).isoformat()


def data_dir() -> Path:
    """Override, else %LOCALAPPDATA%\\Blackout on Windows, else ~/.blackout."""
    override: str = os.environ.get("BLACKOUT_DATA_DIR") or ""
    if override:
        return Path(override)
    if os.name == "nt":
        local: str = os.environ.get("LOCALAPPDATA") or ""
        if local:
            return Path(local) / "Blackout"
        return Path.home() / "Blackout"
    return Path.home() / ".blackout"


def sessions_dir() -> Path:
    """Directory containing session files."""
    return data_dir() / "sessions"


def _chmod_quiet(path: Path, mode: int) -> None:
    try:
        os.chmod(path, mode)
    except Exception:
        pass


def _ensure_private_dir(path: Path) -> None:
    try:
        path.mkdir(parents=True, exist_ok=True)
    except Exception:
        return
    _chmod_quiet(path, 0o700)


def is_valid_id(session_id: Any) -> bool:
    """Only uuid4 hex ids can become paths."""
    return isinstance(session_id, str) and bool(_ID_RE.fullmatch(session_id))


def session_path(session_id: str) -> Optional[Path]:
    """Path for a valid id, otherwise None."""
    if not is_valid_id(session_id):
        return None
    return sessions_dir() / f"{session_id}.json"


def get_lock(session_id: str) -> threading.RLock:
    """Per-session lock."""
    with _locks_guard:
        return _locks.setdefault(session_id, threading.RLock())


def _fix_loaded(record: Dict[str, Any]) -> Dict[str, Any]:
    changed: bool = False
    for task in record.get("tasks", []):
        if isinstance(task, dict) and task.get("status") == "running":
            task["status"] = "failed"
            task.setdefault("conclusion", "任务未完成")
            changed = True
    if changed:
        logger.info("running tasks marked failed on load")
    return record


def save_session(record: Dict[str, Any]) -> Dict[str, Any]:
    """Atomically save; retry replace, otherwise keep cache and do not raise."""
    session_id: str = str(record.get("id", ""))
    path: Optional[Path] = session_path(session_id)
    if path is None:
        raise ValueError("invalid session id")
    record["updated_at"] = now_iso()
    _cache[session_id] = record
    tmp: Path = path.parent / f".{session_id}.{uuid.uuid4().hex}.tmp"
    try:
        _ensure_private_dir(path.parent.parent)
        _ensure_private_dir(path.parent)
        tmp.write_text(json.dumps(record, ensure_ascii=False), encoding="utf-8")
        _chmod_quiet(tmp, 0o600)
    except Exception:
        logger.exception("session write failed; record kept in cache")
        return record
    for attempt in range(6):
        try:
            os.replace(tmp, path)
            _chmod_quiet(path, 0o600)
            return record
        except PermissionError:
            if attempt < 5:
                time.sleep(_REPLACE_DELAYS[attempt])
        except OSError:
            if attempt < 5:
                time.sleep(_REPLACE_DELAYS[attempt])
    logger.error("session replace failed after retries; record kept in cache")
    try:
        tmp.unlink()
    except Exception:
        pass
    return record


def create_session(goal: str) -> Dict[str, Any]:
    """Create, persist, and return a session record."""
    session_id: str = uuid.uuid4().hex
    stamp: str = now_iso()
    record: Dict[str, Any] = {
        "id": session_id, "created_at": stamp, "updated_at": stamp, "status": "active",
        "state": new_state(goal), "history": [], "tasks": [], "sketches": [], "result": None,
        "stats": {"user_turns": 0, "ai_spoke": 0, "listened": 0, "pull_backs": 0, "nudges": 0},
    }
    save_session(record)
    _live[session_id] = dict(DEFAULT_LIVE)
    return record


def load_session(session_id: str) -> Optional[Dict[str, Any]]:
    """Load from disk, converting stale running tasks."""
    path: Optional[Path] = session_path(session_id)
    if path is None or not path.is_file():
        return None
    try:
        record: Any = json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        logger.exception("session load failed")
        return None
    if not isinstance(record, dict):
        return None
    record = _fix_loaded(record)
    _cache[session_id] = record
    return record


def get_session(session_id: str) -> Optional[Dict[str, Any]]:
    """Return cached or disk session, or None."""
    if not is_valid_id(session_id):
        return None
    if session_id in _cache:
        return _cache[session_id]
    return load_session(session_id)


def get_session_copy(session_id: str) -> Optional[Dict[str, Any]]:
    """Deep copy made under the session lock, safe to serialize."""
    if not is_valid_id(session_id):
        return None
    with get_lock(session_id):
        record: Optional[Dict[str, Any]] = get_session(session_id)
        return copy.deepcopy(record) if record is not None else None


def snapshot_session(session_id: str) -> Optional[Dict[str, Any]]:
    """Alias used by snapshot/model/apply flows."""
    return get_session_copy(session_id)


def delete_session(session_id: str) -> bool:
    """Delete under the session lock so a concurrent save cannot revive it."""
    path: Optional[Path] = session_path(session_id)
    if path is None:
        return False
    with get_lock(session_id):
        existed: bool = session_id in _cache or path.is_file()
        _cache.pop(session_id, None)
        _outbox.pop(session_id, None)
        _live.pop(session_id, None)
        try:
            path.unlink()
        except FileNotFoundError:
            pass
        return existed


def list_sessions(limit: int = 50) -> List[Dict[str, Any]]:
    """Recent session summaries, newest first."""
    records: List[Dict[str, Any]] = []
    directory: Path = sessions_dir()
    if directory.is_dir():
        for path in directory.glob("*.json"):
            session_id: str = path.stem
            if not is_valid_id(session_id):
                continue
            record: Optional[Dict[str, Any]] = _cache.get(session_id) or load_session(session_id)
            if record is not None:
                records.append(record)
    for record in _cache.values():
        if all(str(r.get("id")) != str(record.get("id")) for r in records):
            records.append(record)
    records.sort(key=lambda r: str(r.get("updated_at", "")), reverse=True)
    out: List[Dict[str, Any]] = []
    for record in records[:limit]:
        state: Any = record.get("state", {})
        out.append({"id": str(record.get("id", "")), "goal": str(state.get("goal", "")) if isinstance(state, dict) else "", "status": str(record.get("status", "active")), "created_at": str(record.get("created_at", "")), "updated_at": str(record.get("updated_at", ""))})
    return out


def add_announcement(session_id: str, text: str, kind: str = "announcement") -> None:
    """Queue an in-memory announcement."""
    if not is_valid_id(session_id):
        return
    _outbox.setdefault(session_id, []).append({"text": text, "kind": kind})


def drain_announcements(session_id: str) -> List[Dict[str, str]]:
    """Return and clear queued announcements."""
    if not is_valid_id(session_id):
        return []
    return _outbox.pop(session_id, [])


def get_live(session_id: str) -> Dict[str, str]:
    """In-memory live observer values."""
    if not is_valid_id(session_id):
        return dict(DEFAULT_LIVE)
    return dict(_live.get(session_id, DEFAULT_LIVE))


def update_live(session_id: str, **values: str) -> None:
    """Update live observer values; mic uses the unambiguous enum."""
    if not is_valid_id(session_id):
        return
    live: Dict[str, str] = _live.setdefault(session_id, dict(DEFAULT_LIVE))
    for key, value in values.items():
        if key not in DEFAULT_LIVE:
            continue
        text: str = str(value)
        if key == "mic":
            if text == "speaking":
                # Legacy callers meant the user; never store the ambiguity.
                text = "user_speaking"
            if text not in LIVE_MIC_VALUES:
                text = "offline"
        live[key] = text


def clear_memory() -> None:
    """Clear in-memory caches, simulating a restart."""
    _cache.clear()
    _outbox.clear()
    _live.clear()
", "path": "app/store.py"}, {"content": """"Background search and drafting tasks."""
import json
import logging
import os
import re
import uuid
from concurrent.futures import ThreadPoolExecutor
from typing import Any, Dict, List, Optional, Tuple
from urllib.parse import urlparse

from muse_client import DEFAULT_MODEL, create_client
from app import store, summary as summary_mod
from app.prompts import DRAFT_SYSTEM_PROMPT, SEARCH_SYSTEM_PROMPT, build_draft_user_content, build_search_user_content
from app.state import build_map, clean_text

logger: logging.Logger = logging.getLogger(__name__)
_executor: ThreadPoolExecutor = ThreadPoolExecutor(max_workers=4)
BUDGET_MESSAGE: str = "预算已耗尽，本次无法继续，请稍后再试。"
CAP_MESSAGE: str = "这次后台的事够多了，我先记下这个问题。"
_URL_RE: re.Pattern = re.compile(r"https?://\S+|www\.\S+")


def is_budget_error(exc: Exception) -> bool:
    """Detect HTTP 402."""
    if getattr(exc, "status_code", None) == 402:
        return True
    return getattr(getattr(exc, "response", None), "status_code", None) == 402


def max_tasks_per_session() -> int:
    """Per-session background-task ceiling."""
    try:
        return max(0, int(os.environ.get("BLACKOUT_MAX_TASKS_PER_SESSION", "12")))
    except ValueError:
        return 12


def normalize_instruction(instruction: Any) -> str:
    """Instruction with punctuation and spaces removed, for dedup."""
    return clean_text(str(instruction or ""))


def task_block_reason(record: Any, instruction: str) -> Optional[str]:
    """Return 'duplicate', 'cap', or None if a new task may start."""
    if not isinstance(record, dict):
        return None
    tasks_list: Any = record.get("tasks", [])
    if not isinstance(tasks_list, list):
        return None
    wanted: str = normalize_instruction(instruction)
    if wanted:
        for task in tasks_list:
            if isinstance(task, dict) and normalize_instruction(task.get("instruction", "")) == wanted:
                return "duplicate"
    if len(tasks_list) >= max_tasks_per_session():
        return "cap"
    return None


def _attr(value: Any, name: str) -> Any:
    if isinstance(value, dict):
        return value.get(name)
    return getattr(value, name, None)


def _text_blocks(message: Any) -> Tuple[str, List[Tuple[str, str]]]:
    texts: List[str] = []
    titled_urls: List[Tuple[str, str]] = []
    content: Any = _attr(message, "content")
    if isinstance(content, str):
        return content, titled_urls
    if isinstance(content, list):
        for block in content:
            text: Any = _attr(block, "output_text")
            if not isinstance(text, str):
                text = _attr(block, "text")
            if isinstance(text, str):
                texts.append(text)
            annotations: Any = _attr(block, "annotations") or []
            if isinstance(annotations, list):
                for ann in annotations:
                    url: Any = _attr(ann, "url")
                    title: Any = _attr(ann, "title")
                    if isinstance(url, str):
                        titled_urls.append((title if isinstance(title, str) else "", url))
    return "".join(texts), titled_urls


def _message_text_and_sources(resp: Any) -> Tuple[str, List[Dict[str, str]]]:
    output: Any = _attr(resp, "output")
    if not isinstance(output, list):
        text: Any = _attr(resp, "output_text")
        return (text if isinstance(text, str) else ""), []
    messages: List[Any] = [item for item in output if _attr(item, "type") == "message"]
    text: str = ""
    annotation_sources: List[Tuple[str, str]] = []
    if messages:
        text, annotation_sources = _text_blocks(messages[-1])
    sources: List[Dict[str, str]] = []
    seen: set = set()
    def add_source(title: str, url: str) -> None:
        parsed: Any = urlparse(url)
        if parsed.scheme not in ("http", "https") or url in seen or len(sources) >= 8:
            return
        seen.add(url)
        sources.append({"title": title or url, "url": url})
    for item in output:
        if _attr(item, "type") != "web_search_call":
            continue
        results: Any = _attr(item, "results") or []
        if isinstance(results, list):
            for result in results:
                url: Any = _attr(result, "url")
                title: Any = _attr(result, "title")
                if isinstance(url, str):
                    add_source(title if isinstance(title, str) else url, url)
    for title, url in annotation_sources:
        add_source(title, url)
